def gen(rng):
    def fmt(a, b):
        return str(len(a)) + ' ' + str(len(b)) + '\n' + ' '.join(map(str, a)) + '\n' + ' '.join(map(str, b))
    def arr(k, lo, hi):
        return sorted(rng.randint(lo, hi) for _ in range(k))
    tests = [
        fmt([5], []), fmt([], [5]), fmt([1, 1, 1], [1, 1]), fmt([1, 2, 3], [4, 5, 6]),
        fmt([4, 5, 6], [1, 2, 3]), fmt([-10**9, 10**9], [-10**9, 0, 10**9]),
        fmt([1, 3, 5], [2, 4, 6]), fmt([0, 3], [4, 4, 10]),
    ]
    for _ in range(45):
        m = rng.randint(0, 8)
        n = rng.randint(0, 8)
        if m + n == 0:
            m = 1
        tests.append(fmt(arr(m, -6, 6), arr(n, -6, 6)))
    N = 20000
    tests.append(fmt(arr(N, -10**9, 10**9), arr(N, -10**9, 10**9)))
    tests.append(fmt(arr(N, -10**9, 10**9), []))
    tests.append(fmt(arr(1, -10**9, 10**9), arr(N, -10**9, 10**9)))
    tests.append(fmt(arr(N, -5, 5), arr(N, -5, 5)))
    return tests

